#!/usr/bin/env python3
"""Render a draft card file (same schema as data/sejr_arcana.json, plus an optional 'cracker' field) to markdown.

Usage: export_draft.py data/sejr_arcana_draft_fold4.json analysis/arcana_fold4_cards.md
"""
import json, pathlib, sys
cards = json.loads(pathlib.Path(sys.argv[1]).read_text())
out = ["# Fold 4 cards\n",
       "Generated by `tools/export_draft.py` from the draft file. Proposed, not canon: none of these are in the live deck, the draw, or the rule book.\n"]
for c in cards:
    r = c["resource"]
    out.append(f"## {c['name']}\n\n`{c['id']}` · {c['tier']} · {c['matrix'].get('region', '')}\n")
    out.append("**Object.** " + c["object"] + "\n")
    out.append("**Unlock.**\n" + "\n".join("- " + u for u in c["unlock"]) + "\n- Risk: " + c["risk"] + "\n")
    out.append(f"**Resource: {r['name']} ({r['type']}).** " + r["text"] + "\n")
    out.append("**Powers.**\n" + "\n".join("- " + p for p in c["powers"]) + "\n")
    out.append("**Escalation.** " + c["escalation"] + "\n")
    if c.get("cracker"):
        out.append("**Cracker.** " + c["cracker"] + "\n")
    out.append("*Notes:* " + c["notes"] + "\n")
pathlib.Path(sys.argv[2]).write_text("\n".join(out))
print("written", len(cards), "cards")
